{
  "headline": "Alteplase is not on FDA's shortage list as of 2026-10-21; a Genentech 100 mg vial configuration is posted as To Be Discontinued since 2026-05-21",
  "headline_cites": ["D3", "E12"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows alteplase is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "A Genentech, Inc. entry for Alteplase Injection 100 mg vial (NDC 50242-085-27) is posted with status To Be Discontinued, initial posting date 2026-05-21.",
      "cites": ["E12"]
    },
    {
      "text": "The product label for NDC 50242004110 identifies Genentech, Inc. as labeler and manufacturer at two registered plants (FEI 3006129086 and FEI 3007232634).",
      "cites": ["E5", "E10"]
    },
    {
      "text": "FDA inspection records for FEI 3006129086 show VAI classifications in 2015 and 2017, with the most recent known date 2018-01-16.",
      "cites": ["E3", "E4"]
    },
    {
      "text": "FDA inspection records for FEI 3007232634 show VAI classifications from 2012 through 2024, with the most recent inspection end date 2024-04-19 and known date 2024-06-28.",
      "cites": ["E6", "E7", "E8", "E9"]
    },
    {
      "text": "A Class II recall (D-0509-2024) for Cathflo Activase 2 mg vials was initiated 2024-05-20 and terminated, citing deformed stoppers during filling operations.",
      "cites": ["E11"]
    },
    {
      "text": "Current on-hand supply at Corvale East is 191 vials (20.4 days) and at Corvale General is 298 vials (28.6 days) for the 2.2 mg/2 mL presentation.",
      "cites": ["D1", "D2"]
    }
  ]
}
